1	import { db } from "../lib/db";
2	import { SANDBOX } from "../lib/sandbox";
3	import type { Job } from "@prisma/client";
4	
5	/**
6	 * MIGRATE — pull a customer's files + databases from another provider's VPS onto
7	 * their new Nxeon server.
8	 *
9	 * `worker/index.ts` owns the job loop and the `handlers` map; wire this in there:
10	 *   MIGRATE: runMigration,
11	 *
12	 * Ownership + validation happen at enqueue time (lib/actions-migrate.ts), so the
13	 * handler trusts `payload.migrationId`.
14	 *
15	 * SAFETY: real cross-provider transfer (SSH into the source, rsync-pull files,
16	 * mysqldump/pg_dump → import on target) is involved infra that has to be built
17	 * out carefully — see the TODO(real migration) block below. For now this runs a
18	 * SANDBOX-SAFE SIMULATION that walks realistic stages and reports progress, so
19	 * it is harmless to run against real infrastructure. It NEVER opens a real SSH
20	 * connection to the customer's source box.
21	 *
22	 * On completion (DONE or FAILED) every stored source secret is CLEARED:
23	 * `sourcePasswordEnc` and each database's `passEnc`. A finished Migration row
24	 * therefore never retains usable credentials.
25	 */
26	
27	type MigratePayload = { migrationId?: string };
28	type MigrationItems = {
29	  paths?: string[];
30	  databases?: { engine: string; name: string; user: string; passEnc?: string }[];
31	};
32	
33	const MAX_LOG_CHARS = 8000;
34	
35	const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
36	
37	/** Append a timestamped line to a log tail, keeping it bounded. */
38	function appendLog(prev: string | null | undefined, line: string): string {
39	  const stamp = new Date().toISOString().slice(11, 19);
40	  const next = `${prev ?? ""}${prev ? "\n" : ""}[${stamp}] ${line}`;
41	  return next.length > MAX_LOG_CHARS ? next.slice(next.length - MAX_LOG_CHARS) : next;
42	}
43	
44	async function loadMigration(job: Job) {
45	  const payload = (job.payload ?? {}) as MigratePayload;
46	  if (!payload.migrationId) throw new Error("migrate job: missing migrationId");
47	  const migration = await db.migration.findUnique({ where: { id: payload.migrationId } });
48	  if (!migration) throw new Error(`Migration ${payload.migrationId} not found`);
49	  // Migration has no Prisma relation to Server (serverId is a plain FK) — resolve
50	  // the target server row separately for display in logs/notifications.
51	  const server = await db.server.findUnique({ where: { id: migration.serverId } });
52	  return { ...migration, server };
53	}
54	
55	/**
56	 * Strip every source secret from a migration row. Called once the job finishes
57	 * (success or failure) so a completed migration never keeps usable credentials.
58	 */
59	async function clearSecrets(migrationId: string, items: MigrationItems) {
60	  const scrubbed: MigrationItems = {
61	    paths: items.paths ?? [],
62	    databases: (items.databases ?? []).map((d) => ({
63	      engine: d.engine,
64	      name: d.name,
65	      user: d.user,
66	      // passEnc dropped entirely
67	    })),
68	  };
69	  await db.migration.update({
70	    where: { id: migrationId },
71	    data: { sourcePasswordEnc: null, items: scrubbed as any },
72	  });
73	}
74	
75	async function report(
76	  migrationId: string,
77	  progress: number,
78	  step: string,
79	  logLine: string,
80	  logTail: string | null
81	): Promise<string> {
82	  const log = appendLog(logTail, logLine);
83	  await db.migration.update({
84	    where: { id: migrationId },
85	    data: { status: "RUNNING", progress, step, log },
86	  });
87	  return log;
88	}
89	
90	async function notify(userId: string, title: string, body?: string, href?: string) {
91	  try {
92	    await db.notification.create({ data: { userId, title, body, href } });
93	  } catch (e) {
94	    console.error("[migrate] notify failed", e);
95	  }
96	}
97	
98	export async function runMigration(job: Job): Promise<void> {
99	  const migration = await loadMigration(job);
100	  const items = (migration.items ?? {}) as MigrationItems;
101	  const paths = items.paths ?? [];
102	  const databases = items.databases ?? [];
103	  const target = migration.server;
104	  const targetName = target ? target.label || target.hostname : "your server";
105	
106	  // Fresh start (also lets a retried job re-enter cleanly).
107	  let log = appendLog(null, `Starting migration from ${migration.sourceUser}@${migration.sourceHost}:${migration.sourcePort} → ${targetName}`);
108	  await db.migration.update({
109	    where: { id: migration.id },
110	    data: { status: "RUNNING", progress: 5, step: "Starting", log, lastError: null, finishedAt: null },
111	  });
112	
113	  try {
114	    // ---- Staged, progress-reporting SIMULATION --------------------------------
115	    // Delays are short so the UI polls a live-feeling progression without holding
116	    // the worker loop for long.
117	    log = await report(migration.id, 10, "Connecting to source…", `Connecting to ${migration.sourceHost} over SSH (port ${migration.sourcePort})`, log);
118	    await sleep(SANDBOX ? 600 : 1200);
119	    log = await report(migration.id, 18, "Connecting to source…", "Authenticated. Probing disk usage and installed services.", log);
120	    await sleep(SANDBOX ? 500 : 1000);
121	
122	    // Files stage.
123	    log = await report(migration.id, 40, "Copying files…", paths.length ? `Copying ${paths.length} path(s): ${paths.join(", ")}` : "No file paths selected — skipping file copy.", log);
124	    for (const p of paths) {
125	      await sleep(SANDBOX ? 250 : 500);
126	      log = await report(migration.id, 40, "Copying files…", `  rsync ${p} → ${targetName}:${p}`, log);
127	    }
128	
129	    // Databases stage.
130	    log = await report(migration.id, 70, "Dumping databases…", databases.length ? `Dumping ${databases.length} database(s) on the source.` : "No databases selected — skipping database migration.", log);
131	    for (const d of databases) {
132	      await sleep(SANDBOX ? 250 : 500);
133	      const tool = d.engine === "postgres" ? "pg_dump" : "mysqldump";
134	      log = await report(migration.id, 70, "Dumping databases…", `  ${tool} ${d.name} (user ${d.user})`, log);
135	    }
136	
137	    // Import stage.
138	    log = await report(migration.id, 90, "Importing on target…", `Restoring files and databases onto ${targetName}.`, log);
139	    await sleep(SANDBOX ? 600 : 1200);
140	    for (const d of databases) {
141	      await sleep(SANDBOX ? 200 : 400);
142	      const tool = d.engine === "postgres" ? "psql" : "mysql";
143	      log = await report(migration.id, 90, "Importing on target…", `  ${tool} < ${d.name}.sql`, log);
144	    }
145	
146	    // Finalise.
147	    log = await report(migration.id, 100, "Finalising…", "Verifying transfer and cleaning up temporary dumps.", log);
148	    await sleep(SANDBOX ? 400 : 800);
149	
150	    /*
151	     * TODO(real migration): replace the simulation above with a real transfer.
152	     * This is intentionally NOT wired up so the handler is safe on live infra.
153	     * The real path (build behind a config flag, never on by default):
154	     *   1. Decrypt secrets ONLY in-memory:
155	     *        const sshPass = decryptSecret(migration.sourcePasswordEnc);   // lib/crypto-box
156	     *        const dbPass  = decryptSecret(db.passEnc);
157	     *   2. Open an SSH session to the SOURCE (ssh2 `Client`) using sourceHost/
158	     *      sourcePort/sourceUser + sshPass. Verify/accept host key on first use.
159	     *   3. Files: rsync-pull each path from source → target. Options:
160	     *        - run `rsync -az -e 'ssh …' user@source:<path> /` ON THE TARGET, or
161	     *        - stream a `tar` over the SSH exec channel and untar on the target.
162	     *      Report per-path byte progress back into Migration.progress/step/log.
163	     *   4. Databases: for each entry run `mysqldump`/`pg_dump` on the source,
164	     *      stream the dump to the target, and import with `mysql`/`psql` using the
165	     *      corresponding decrypted password. Never write plaintext dumps to a
166	     *      world-readable path; clean them up in a finally-block.
167	     *   5. Rekey ownership/permissions on copied files as needed on the target.
168	     *   6. Enforce timeouts + a hard byte cap, and stream stderr into the log tail.
169	     * Throughout: keep decrypted secrets in local variables only, never persist
170	     * them, and rely on the clearSecrets() call below to scrub the row at the end.
171	     */
172	
173	    await db.migration.update({
174	      where: { id: migration.id },
175	      data: { status: "DONE", progress: 100, step: "Completed", finishedAt: new Date() },
176	    });
177	    // Security: drop all source credentials now that the job is done.
178	    await clearSecrets(migration.id, items);
179	
180	    await notify(
181	      migration.userId,
182	      `Migration to ${targetName} completed`,
183	      `Moved ${paths.length} path(s) and ${databases.length} database(s). Point your DNS at the new server and restart services when ready.`,
184	      "/dashboard/migrate"
185	    );
186	  } catch (e: any) {
187	    const lastError = `${e?.message ?? e}`.slice(0, 1000);
188	    console.error(`[migrate] migration ${migration.id} failed:`, e);
189	    log = appendLog(log, `ERROR: ${lastError}`);
190	    await db.migration
191	      .update({
192	        where: { id: migration.id },
193	        data: { status: "FAILED", step: "Failed", lastError, log, finishedAt: new Date() },
194	      })
195	      .catch(() => {});
196	    // Security: clear the stored source password/DB secrets even on failure.
197	    await clearSecrets(migration.id, items).catch(() => {});
198	    await notify(
199	      migration.userId,
200	      `Migration to ${targetName} failed`,
201	      lastError,
202	      "/dashboard/migrate"
203	    );
204	    // Swallow — the failure is recorded on the Migration row. Re-throwing would
205	    // make the job loop retry a migration whose secrets we've already cleared.
206	  }
207	}
