1	/**
2	 * Server-side SFTP proxy for the in-portal file manager.
3	 *
4	 * This is a plain (non-"use server") module so it can be imported by both the
5	 * server actions (lib/actions-files.ts) and the upload/download route handler.
6	 * It never runs in the browser — the customer's root credentials stay on the
7	 * server; the browser only ever talks to our own actions/route.
8	 *
9	 * Connection target is derived EXACTLY like the server detail page:
10	 *   - dedicated-IP servers connect to their own IP on port 22
11	 *   - NAT servers use PUBLIC_IP + the forwarded SSH port
12	 * Username is always "root"; password is `server.rootPassword`.
13	 *
14	 * SANDBOX: on staging (NXEON_SANDBOX=1) no real SSH connection is ever opened —
15	 * every op is backed by a small in-memory simulated filesystem so the whole
16	 * file-manager UX works end to end without a live VM.
17	 */
18	import SftpClient from "ssh2-sftp-client";
19	import { SANDBOX } from "./sandbox";
20	
21	/** The minimal shape of a Server we need to open a connection. */
22	export type SftpServer = {
23	  id: string;
24	  rootPassword: string | null;
25	  sshPort: number | null;
26	  dedicatedIp?: { address: string } | null;
27	};
28	
29	export type SftpEntry = {
30	  name: string;
31	  /** "d" directory, "-" file, "l" symlink, etc. (ssh2-sftp-client `type`). */
32	  type: string;
33	  isDirectory: boolean;
34	  size: number;
35	  /** Unix mtime in ms. */
36	  modifiedMs: number;
37	  /** Numeric permission bits (e.g. 0o644), or null if unknown. */
38	  mode: number | null;
39	};
40	
41	export type SftpStat = {
42	  isDirectory: boolean;
43	  size: number;
44	  modifiedMs: number;
45	  mode: number | null;
46	};
47	
48	const CONNECT_TIMEOUT_MS = 10_000;
49	
50	/** Max length for any absolute path we accept from the client. */
51	export const MAX_PATH_LEN = 4096;
52	/** Max length for a single path segment (file/folder name). */
53	export const MAX_NAME_LEN = 255;
54	
55	/**
56	 * Normalize + validate an absolute POSIX path coming from the browser. Rejects
57	 * relative paths, `..` traversal, NUL bytes, and over-long paths. Returns a
58	 * cleaned absolute path (collapsed slashes, resolved `.`), always starting with
59	 * "/". Throws on anything suspicious — callers surface the message.
60	 */
61	export function normalizePath(input: string): string {
62	  if (typeof input !== "string") throw new Error("Invalid path.");
63	  if (input.length > MAX_PATH_LEN) throw new Error("Path is too long.");
64	  if (input.includes("\0")) throw new Error("Invalid path.");
65	  if (!input.startsWith("/")) throw new Error("Path must be absolute.");
66	
67	  const out: string[] = [];
68	  for (const part of input.split("/")) {
69	    if (part === "" || part === ".") continue;
70	    if (part === "..") throw new Error("Path traversal is not allowed.");
71	    if (part.length > MAX_NAME_LEN) throw new Error("A path segment is too long.");
72	    out.push(part);
73	  }
74	  return "/" + out.join("/");
75	}
76	
77	/**
78	 * Validate a single new file/folder name — no slashes, no traversal, no NUL,
79	 * not "." or "..". Returns the name unchanged if valid.
80	 */
81	export function validateName(name: string): string {
82	  if (typeof name !== "string" || name.length === 0) throw new Error("A name is required.");
83	  if (name.length > MAX_NAME_LEN) throw new Error("Name is too long.");
84	  if (name.includes("/") || name.includes("\0")) throw new Error("Name contains invalid characters.");
85	  if (name === "." || name === "..") throw new Error("That name is not allowed.");
86	  return name;
87	}
88	
89	/** Join a validated absolute dir with a validated name, re-normalizing. */
90	export function joinPath(dir: string, name: string): string {
91	  return normalizePath(`${dir}/${name}`);
92	}
93	
94	/**
95	 * Resolve the {host, port} for a server, mirroring the server detail page:
96	 * dedicated IP -> :22, otherwise PUBLIC_IP:sshPort.
97	 */
98	export function connectionTarget(server: SftpServer): { host: string; port: number } | null {
99	  const dedicated = !!server.dedicatedIp;
100	  const host = dedicated ? server.dedicatedIp!.address : process.env.PUBLIC_IP || "";
101	  const port = dedicated ? 22 : server.sshPort;
102	  if (!host || !port) return null;
103	  return { host, port };
104	}
105	
106	/**
107	 * Open an SFTP connection, run `fn(client)`, and ALWAYS close it (finally).
108	 * In SANDBOX mode this is bypassed entirely — callers below short-circuit to
109	 * the in-memory filesystem before ever reaching here.
110	 */
111	export async function withSftp<T>(
112	  server: SftpServer,
113	  fn: (client: SftpClient) => Promise<T>
114	): Promise<T> {
115	  if (SANDBOX) {
116	    throw new Error("withSftp must not be called in sandbox mode");
117	  }
118	  const target = connectionTarget(server);
119	  if (!target) throw new Error("Server is not reachable yet — connection details are pending.");
120	  if (!server.rootPassword) throw new Error("Server has no root password set.");
121	
122	  const client = new SftpClient();
123	  try {
124	    await client.connect({
125	      host: target.host,
126	      port: target.port,
127	      username: "root",
128	      password: server.rootPassword,
129	      readyTimeout: CONNECT_TIMEOUT_MS,
130	    });
131	    return await fn(client);
132	  } finally {
133	    try {
134	      await client.end();
135	    } catch {
136	      /* best-effort close */
137	    }
138	  }
139	}
140	
141	// ----------------------------------------------------------------------------
142	// Sandbox in-memory filesystem
143	// ----------------------------------------------------------------------------
144	
145	type SimNode =
146	  | { type: "dir"; mtime: number; mode: number; children: Record<string, SimNode> }
147	  | { type: "file"; mtime: number; mode: number; content: string };
148	type SimDir = Extract<SimNode, { type: "dir" }>;
149	
150	/** One simulated filesystem per server id, lazily seeded. */
151	const globalForSim = globalThis as unknown as { __nxeonSftpSim?: Map<string, SimNode> };
152	const simStore: Map<string, SimNode> = globalForSim.__nxeonSftpSim ?? new Map();
153	globalForSim.__nxeonSftpSim = simStore;
154	
155	function seedSim(): SimNode {
156	  const now = Date.now();
157	  const file = (content: string, mode = 0o644): SimNode => ({
158	    type: "file",
159	    mtime: now,
160	    mode,
161	    content,
162	  });
163	  const dir = (children: Record<string, SimNode>, mode = 0o755): SimNode => ({
164	    type: "dir",
165	    mtime: now,
166	    mode,
167	    children,
168	  });
169	  return dir({
170	    root: dir({
171	      "readme.txt": file(
172	        "Welcome to your VPS (sandbox).\n\nThis is a simulated filesystem shown on the staging\nenvironment — no real SSH connection is made.\n"
173	      ),
174	      ".bashrc": file("# ~/.bashrc\nexport PATH=$PATH:/usr/local/bin\n"),
175	      projects: dir({
176	        "app.js": file("console.log('hello from your server');\n"),
177	        "notes.md": file("# Notes\n\n- Edit me from the file manager.\n"),
178	      }),
179	    }),
180	    etc: dir({
181	      "hostname": file("nxeon-vps\n"),
182	      "os-release": file('PRETTY_NAME="Ubuntu 24.04 LTS"\n', 0o644),
183	    }),
184	    var: dir({
185	      log: dir({
186	        "syslog": file("Jan  1 00:00:00 nxeon-vps systemd[1]: Started sandbox.\n"),
187	      }),
188	      www: dir({
189	        html: dir({
190	          "index.html": file("<!doctype html><h1>It works</h1>\n"),
191	        }),
192	      }),
193	    }),
194	    tmp: dir({}),
195	  });
196	}
197	
198	function simRoot(serverId: string): SimNode {
199	  let node = simStore.get(serverId);
200	  if (!node) {
201	    node = seedSim();
202	    simStore.set(serverId, node);
203	  }
204	  return node;
205	}
206	
207	/** Convert an rwx rights triad ("rwx","r-x","r--") into an octal mode integer. */
208	function rightsToMode(rights: { user: string; group: string; other: string }): number | null {
209	  if (!rights) return null;
210	  const bits = (s: string): number =>
211	    (s.includes("r") ? 4 : 0) + (s.includes("w") ? 2 : 0) + (s.includes("x") ? 1 : 0);
212	  return (bits(rights.user) << 6) | (bits(rights.group) << 3) | bits(rights.other);
213	}
214	
215	function splitPath(p: string): string[] {
216	  return p.split("/").filter((s) => s.length > 0);
217	}
218	
219	function simResolve(serverId: string, p: string): SimNode | null {
220	  let node = simRoot(serverId);
221	  for (const part of splitPath(p)) {
222	    if (node.type !== "dir") return null;
223	    const next = node.children[part];
224	    if (!next) return null;
225	    node = next;
226	  }
227	  return node;
228	}
229	
230	function simParent(serverId: string, p: string): { parent: SimDir; name: string } | null {
231	  const parts = splitPath(p);
232	  if (parts.length === 0) return null;
233	  const name = parts[parts.length - 1];
234	  const parentPath = "/" + parts.slice(0, -1).join("/");
235	  const parent = simResolve(serverId, parentPath);
236	  if (!parent || parent.type !== "dir") return null;
237	  return { parent, name };
238	}
239	
240	// ----------------------------------------------------------------------------
241	// Typed operations (sandbox-aware)
242	// ----------------------------------------------------------------------------
243	
244	export async function listDir(server: SftpServer, path: string): Promise<SftpEntry[]> {
245	  if (SANDBOX) {
246	    const node = simResolve(server.id, path);
247	    if (!node) throw new Error("No such directory.");
248	    if (node.type !== "dir") throw new Error("Not a directory.");
249	    return Object.entries(node.children)
250	      .map(([name, child]) => ({
251	        name,
252	        type: child.type === "dir" ? "d" : "-",
253	        isDirectory: child.type === "dir",
254	        size: child.type === "file" ? Buffer.byteLength(child.content) : 0,
255	        modifiedMs: child.mtime,
256	        mode: child.mode,
257	      }))
258	      .sort((a, b) =>
259	        a.isDirectory === b.isDirectory ? a.name.localeCompare(b.name) : a.isDirectory ? -1 : 1
260	      );
261	  }
262	
263	  return withSftp(server, async (client) => {
264	    const list = await client.list(path);
265	    return list
266	      .map((e) => ({
267	        name: e.name,
268	        type: e.type,
269	        isDirectory: e.type === "d",
270	        size: e.size,
271	        modifiedMs: e.modifyTime,
272	        // ssh2-sftp-client's list() returns rwx `rights` strings, not a numeric
273	        // mode — derive the octal permission bits from them.
274	        mode: rightsToMode(e.rights),
275	      }))
276	      .sort((a, b) =>
277	        a.isDirectory === b.isDirectory ? a.name.localeCompare(b.name) : a.isDirectory ? -1 : 1
278	      );
279	  });
280	}
281	
282	export async function statPath(server: SftpServer, path: string): Promise<SftpStat> {
283	  if (SANDBOX) {
284	    const node = simResolve(server.id, path);
285	    if (!node) throw new Error("No such file or directory.");
286	    return {
287	      isDirectory: node.type === "dir",
288	      size: node.type === "file" ? Buffer.byteLength(node.content) : 0,
289	      modifiedMs: node.mtime,
290	      mode: node.mode,
291	    };
292	  }
