/** Per-command wall-clock cap (rsync/DB copies can legitimately be long). */
const REAL_EXEC_TIMEOUT_MS = 30 * 60_000; // 30 min
/** Shorter cap for cheap probes (package detection, db create). */
const REAL_PROBE_TIMEOUT_MS = 5 * 60_000; // 5 min
/** Cap on how much of a stream we retain in memory (stdout/stderr each). */
const STREAM_KEEP = 64_000;

/**
 * POSIX single-quote a value for safe inclusion in a shell command. Wrapping in
 * single quotes and replacing embedded `'` with `'\''` is inert under nesting,
 * so shq(shq(x)) is still correct — which is what lets us build the "run ssh on
 * the target, which runs a dump on the source" pipelines below.
 */
function shq(s: string): string {
  return "'" + String(s).replace(/'/g, "'\\''") + "'";
}

/** Open one SSH connection to the target Nxeon server (root + rootPassword). */
function connectTarget(host: string, port: number, password: string): Promise<Client> {
  return new Promise((resolve, reject) => {
    const conn = new Client();
    const timer = setTimeout(() => {
      try { conn.end(); } catch { /* noop */ }
      reject(new Error(`SSH connect to target ${host}:${port} timed out`));
    }, 20_000);
    conn.on("ready", () => { clearTimeout(timer); resolve(conn); });
    conn.on("error", (e) => { clearTimeout(timer); reject(e); });
    conn.connect({ host, port, username: "root", password, readyTimeout: 20_000 });
  });
}

/**
 * Run one command on the target over the open SSH connection. Streams stdout +
 * stderr into `onData` (used for live progress), enforces a timeout, and caps
 * retained output. Resolves with the exit code and captured tails.
 */
function execTarget(
  conn: Client,
  cmd: string,
  opts: { timeoutMs: number; onData?: (chunk: string) => void }
): Promise<{ code: number; stdout: string; stderr: string }> {
  return new Promise((resolve, reject) => {
    conn.exec(cmd, (err, stream) => {
      if (err) return reject(err);
      let stdout = "";
      let stderr = "";
      const timer = setTimeout(() => {
        try { stream.close(); } catch { /* noop */ }
        reject(new Error(`Command timed out after ${opts.timeoutMs}ms`));
      }, opts.timeoutMs);
      stream.on("close", (code: number | null) => {
        clearTimeout(timer);
        resolve({ code: code ?? 0, stdout, stderr });
      });
      stream.on("data", (d: Buffer) => {
        const s = d.toString();
        stdout = (stdout + s).slice(-STREAM_KEEP);
        opts.onData?.(s);
      });
      stream.stderr.on("data", (d: Buffer) => {
        const s = d.toString();
        stderr = (stderr + s).slice(-STREAM_KEEP);
        opts.onData?.(s);
      });
    });
  });
}

/** SSH options the target uses to reach the source (non-interactive, no host-key prompt). */
function sourceSshOpts(srcPort: number): string {
  return `ssh -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null -o ConnectTimeout=20 -p ${srcPort}`;
}

type RealCtx = {
  migrationId: string;
  conn: Client;
  sshPass: string;
  srcUser: string;
  srcHost: string;
  srcPort: number;
};

/**
 * Ensure rsync + sshpass exist on the target, installing them via the detected
 * package manager (apt-get / dnf / yum) if missing. Returns nothing; throws on
 * failure to install.
 */
async function ensureTargetTools(ctx: RealCtx, onData: (s: string) => void): Promise<void> {
  const script = [
    "set -e",
    // Only install if something is actually missing.
    'if command -v rsync >/dev/null 2>&1 && command -v sshpass >/dev/null 2>&1; then echo "tools present"; exit 0; fi',
    'if command -v apt-get >/dev/null 2>&1; then',
    "  export DEBIAN_FRONTEND=noninteractive; apt-get update -y && apt-get install -y rsync sshpass;",
    "elif command -v dnf >/dev/null 2>&1; then",
    "  dnf install -y rsync sshpass || (dnf install -y epel-release && dnf install -y rsync sshpass);",
    "elif command -v yum >/dev/null 2>&1; then",
    "  yum install -y rsync sshpass || (yum install -y epel-release && yum install -y rsync sshpass);",
    "else echo 'no supported package manager found' >&2; exit 1; fi",
  ].join("\n");
  const r = await execTarget(ctx.conn, `bash -c ${shq(script)}`, {
    timeoutMs: REAL_PROBE_TIMEOUT_MS,
    onData,
  });
  if (r.code !== 0) {
    throw new Error(`Failed to install rsync/sshpass on target: ${r.stderr.slice(-500) || `exit ${r.code}`}`);
  }
}

/**
 * rsync-pull one path from the source onto the target at the same absolute path.
 * We create the parent dir on the target and copy the path into it, so both
 * files and directories land at their original location.
 */
function buildRsyncCmd(ctx: RealCtx, path: string): string {
  const parent = path.replace(/\/+$/, "").replace(/\/[^/]*$/, "") || "/";
  const remote = `${ctx.srcUser}@${ctx.srcHost}:${path}`;
  // sshpass -p '<src>' rsync -az --info=progress2 -e 'ssh ... -p <port>' user@host:<path> <parent>/
  return [
    "mkdir -p", shq(parent), "&&",
    "sshpass", "-p", shq(ctx.sshPass),
    "rsync", "-az", "--info=progress2", "--timeout=600",
    "-e", shq(sourceSshOpts(ctx.srcPort)),
    shq(remote), shq(parent.replace(/\/$/, "") + "/"),
  ].join(" ");
}

/**
 * Copy one database. The whole dump→import pipeline runs on the TARGET: the
 * target SSHes into the source, runs mysqldump/pg_dump there, and pipes the
 * stream straight into mysql/psql locally. The DB entry's decrypted password is
 * used both to authenticate the dump on the source and the import on the target
 * (the customer's DB user/password is assumed re-created on the new box).
 */
function buildDbCmd(
  ctx: RealCtx,
  d: { engine: string; name: string; user: string; pass: string }
): string {
  const ssh = `sshpass -p ${shq(ctx.sshPass)} ${sourceSshOpts(ctx.srcPort)} ${shq(`${ctx.srcUser}@${ctx.srcHost}`)}`;
  let pipeline: string;

  if (d.engine === "postgres") {
    // Remote dump command (runs on the source), then piped into psql on target.
    const remoteDump = `PGPASSWORD=${shq(d.pass)} pg_dump -U ${shq(d.user)} -h 127.0.0.1 ${shq(d.name)}`;
    pipeline = [
      "set -o pipefail;",
      // Create the DB on the target if it isn't there (ignore "already exists").
      `PGPASSWORD=${shq(d.pass)} createdb -U ${shq(d.user)} -h 127.0.0.1 ${shq(d.name)} 2>/dev/null || true;`,
      `${ssh} ${shq(remoteDump)}`,
      `| PGPASSWORD=${shq(d.pass)} psql -U ${shq(d.user)} -h 127.0.0.1 ${shq(d.name)}`,
    ].join(" ");
  } else {
    // mysql / mariadb
    const remoteDump = `mysqldump --single-transaction --routines --triggers -u${shq(d.user)} -p${shq(d.pass)} ${shq(d.name)}`;
    pipeline = [
      "set -o pipefail;",
      `mysql -u${shq(d.user)} -p${shq(d.pass)} -e ${shq("CREATE DATABASE IF NOT EXISTS \\`" + d.name.replace(/`/g, "") + "\\`")};`,
      `${ssh} ${shq(remoteDump)}`,
      `| mysql -u${shq(d.user)} -p${shq(d.pass)} ${shq(d.name)}`,
    ].join(" ");
  }
  return `bash -c ${shq(pipeline)}`;
}

/**
 * Drive a real cross-provider migration. Reports progress into the Migration row
 * and returns the final log tail so the shared completion block can continue.
 * Throws on any failure (the caller's catch records FAILED + clears secrets).
 */
async function runRealMigration(args: {
  migration: { id: string; sourceUser: string; sourceHost: string; sourcePort: number; sourcePasswordEnc: string | null; server: any };
  paths: string[];
  databases: { engine: string; name: string; user: string; passEnc?: string }[];
  targetName: string;
  log: string;
}): Promise<string> {
  const { migration, paths, databases, targetName } = args;
  let log = args.log;

  // 1. Decrypt secrets — kept only in local variables, never persisted.
  const sshPass = decryptSecret(migration.sourcePasswordEnc);
  if (!sshPass) throw new Error("Could not decrypt source SSH password (missing or wrong AUTH_SECRET).");

  // 2. Derive the TARGET connection exactly like lib/sftp (dedicated IP -> :22,
  //    otherwise PUBLIC_IP:sshPort; user is root, password is server.rootPassword).
  const target = migration.server;
  if (!target) throw new Error("Target server row not found.");
  const tgt = connectionTarget(target);
  if (!tgt) throw new Error("Target server is not reachable yet — connection details are pending.");
  if (!target.rootPassword) throw new Error("Target server has no root password set.");

  log = await report(migration.id, 8, "Connecting to target…", `Opening SSH to target ${tgt.host}:${tgt.port}`, log);
  const conn = await connectTarget(tgt.host, tgt.port, target.rootPassword);

  const ctx: RealCtx = {
    migrationId: migration.id,
    conn,
    sshPass,
    srcUser: migration.sourceUser,
    srcHost: migration.sourceHost,
    srcPort: migration.sourcePort,
  };

  // Throttled log flusher for streamed rsync/dump output (avoid a DB write per
  // chunk). Captures the latest non-empty line and flushes at most every ~2.5s.
  let pendingLine = "";
  let lastFlush = 0;
  const makeOnData = (progress: number, step: string) => (chunk: string) => {
    const line = chunk.split(/[\r\n]+/).map((l) => l.trim()).filter(Boolean).pop();
    if (line) pendingLine = line;
    const now = Date.now();
    if (pendingLine && now - lastFlush > 2500) {
      lastFlush = now;
      const line = pendingLine;
      pendingLine = "";
      // Fire-and-forget; ordering of these interim updates doesn't matter.
      report(migration.id, progress, step, `  ${line}`.slice(0, 400), log)
        .then((l) => { log = l; })
        .catch(() => { /* interim update failure is non-fatal */ });
    }
  };

  try {
    // 3. Make sure the transfer tools exist on the target.
    log = await report(migration.id, 12, "Preparing target…", "Ensuring rsync + sshpass are installed on the target.", log);
    await ensureTargetTools(ctx, makeOnData(12, "Preparing target…"));

    // 4. Files — rsync-pull each selected path onto the target.
    if (paths.length === 0) {
      log = await report(migration.id, 55, "Copying files…", "No file paths selected — skipping file copy.", log);
    } else {
      for (let i = 0; i < paths.length; i++) {
        const p = paths[i];
        // Files occupy the 15–55 progress band.
        const base = 15 + Math.round((i / paths.length) * 40);
        log = await report(migration.id, base, "Copying files…", `rsync ${p} (source → ${targetName})`, log);
        const r = await execTarget(ctx.conn, buildRsyncCmd(ctx, p), {
          timeoutMs: REAL_EXEC_TIMEOUT_MS,
          onData: makeOnData(base, "Copying files…"),
        });
        if (r.code !== 0) {
          throw new Error(`rsync of ${p} failed (exit ${r.code}): ${r.stderr.slice(-500)}`);
        }
        log = await report(migration.id, 15 + Math.round(((i + 1) / paths.length) * 40), "Copying files…", `  done: ${p}`, log);
      }
    }

    // 5. Databases — dump on source, import on target, per engine.
    if (databases.length === 0) {
      log = await report(migration.id, 95, "Migrating databases…", "No databases selected — skipping database migration.", log);
    } else {
      for (let i = 0; i < databases.length; i++) {
        const d = databases[i];
        const pass = decryptSecret(d.passEnc) ?? "";
        const tool = d.engine === "postgres" ? "pg_dump/psql" : "mysqldump/mysql";
        const base = 60 + Math.round((i / databases.length) * 35);
        log = await report(migration.id, base, "Migrating databases…", `${tool}: ${d.name} (user ${d.user})`, log);
        const r = await execTarget(ctx.conn, buildDbCmd(ctx, { engine: d.engine, name: d.name, user: d.user, pass }), {
          timeoutMs: REAL_EXEC_TIMEOUT_MS,
          onData: makeOnData(base, "Migrating databases…"),
        });
        if (r.code !== 0) {
          throw new Error(`Database ${d.name} migration failed (exit ${r.code}): ${r.stderr.slice(-500)}`);
        }
        log = await report(migration.id, 60 + Math.round(((i + 1) / databases.length) * 35), "Migrating databases…", `  done: ${d.name}`, log);
      }
    }

    log = await report(migration.id, 100, "Finalising…", "Transfer complete. Restart services and point DNS at the new server when ready.", log);
    return log;
  } finally {
    try { conn.end(); } catch { /* best-effort close */ }
  }
}

